function makeAmbience(){const mk=(type,f,q)=>{const s=audio.createBufferSource();s.buffer=noise;s.loop=true;const fl=audio.createBiquadFilter();fl.type=type;fl.frequency.value=f;fl.Q.value=q;const g=audio.createGain();g.gain.value=0;s.connect(fl);fl.connect(g);g.connect(master);s.start();return {g,fl};};return {wind:mk('bandpass',480,.6),rain:mk('highpass',1400,.5),birdT:2,cricketT:1};}
function updateAmbience(dt){if(!ambience||audio.state!=='running')return;const a=env.atmo;const playing=state.screen==='playing';const t=audio.currentTime;ambience.wind.g.gain.setTargetAtTime(playing?.05+.05*Art.uniforms.wind.value:.02,t,.5);ambience.wind.fl.frequency.setTargetAtTime(380+Math.sin(state.time*.3)*120,t,.8);ambience.rain.g.gain.setTargetAtTime(playing?a.rain*.18:0,t,.5);
  ambience.birdT-=dt;if(ambience.birdT<=0&&playing&&a.day>.6&&a.rain<.3){ambience.birdT=2+random()*6;const n=2+Math.floor(random()*4),base=2400+random()*1800;for(let i=0;i<n;i++){const o=audio.createOscillator(),g=audio.createGain(),at=t+i*.12;o.frequency.setValueAtTime(base,at);o.frequency.exponentialRampToValueAtTime(base*(1.3+random()*.4),at+.07);env_(g,at,.04,.09);const p=audio.createStereoPanner();p.pan.value=random()*2-1;o.connect(g);g.connect(p);p.connect(master);o.start(at);o.stop(at+.1);}}
  ambience.cricketT-=dt;if(ambience.cricketT<=0&&playing&&a.night>.6&&a.rain<.3){ambience.cricketT=.6+random()*1.2;for(let i=0;i<3;i++){const o=audio.createOscillator(),g=audio.createGain(),at=t+i*.05;o.frequency.value=4300+random()*300;env_(g,at,.025,.03);o.connect(g);g.connect(master);o.start(at);o.stop(at+.04);}}}
