  state.mode=mode;state.matchNo++;state.time=0;state.kills=state.shots=state.hits=state.damageDealt=0;state.zone=new C.Zone(C.rng(7831+state.matchNo));state.action=null;state.activeSlot=0;state.fireCd=state.recoil=state.recoilYaw=state.bloom=state.flash=state.hurt=state.hit=state.suppress=state.trauma=0;state.shootHeld=state.ads=false;state.semiReady=true;state.feed=[];state.activeBullets=0;state.accumulator=0;state.benchmarkTime=0;state.benchFrames=[];state.benchmark=null;state.droppedTime=0;state.steps=0;state.streak=0;state.zip=null;
  Object.assign(player,{hp:100,armor:50,alive:true,onGround:true,yaw:0,pitch:0,medkits:2,plates:1,grenades:2,lastHit:-100,lastShot:-100});player.pos.set(SP.x,C.heightAt(SP.x,SP.z),SP.z);player.vel.set(0,0,0);player.slots=[C.makeWeapon('ar5'),C.makeWeapon('p9')];player.weapon=player.slots[0];player.reserves=Object.fromEntries(C.AMMO.map(k=>[k,k==='5.56'?120:k==='9mm'?45:0]));
