    if(target&&a.targetVisible&&a.reaction<=0&&state.time>3){const lateral=Math.hypot(target.vel.x,target.vel.z);a.aimError=Math.max(D.minErr,a.aimError*Math.exp(-dt*D.converge*(a.skill)))+lateral*.0009*dt*10;a.cooldown-=dt;
      const sniper=['dmr','sniper'].includes(a.weapon.def.shape);const range=Math.min(110,a.weapon.def.range);const td=a.pos.distanceTo(target.pos);
      if(a.cooldown<=0&&td<range&&(!sniper||a.aimError<.045)){if(a.burst<=0)a.burst=a.weapon.def.auto?2+Math.floor(random()*3):1;fireBot(a,target);a.burst--;const rate=a.weapon.def.rate*D.rate;a.cooldown=a.burst>0?1/rate*(1+random()*.3):(.45+random()*.7)*D.pause+1/rate+td*.004;}}
    const look=target&&a.targetVisible?target.pos:{x:a.pos.x+a.vel.x,z:a.pos.z+a.vel.z};const angle=(Math.abs(a.vel.x)+Math.abs(a.vel.z)>.1||target)?Math.atan2(look.x-a.pos.x,look.z-a.pos.z):a.yaw;let diff=angle-a.yaw;while(diff>Math.PI)diff-=Math.PI*2;while(diff<-Math.PI)diff+=Math.PI*2;a.yaw+=diff*Math.min(1,dt*(target?9:5));
