  const aim=1;P.shoulderR.rotation.set(-1.25*aim+pitch*.0,0,.1);P.elbowR.rotation.set(-.55,0,0);P.shoulderL.rotation.set(-1.35*aim,0,.62);P.elbowL.rotation.set(-.65,0,0);
  if(a.reloadTimer>0){P.shoulderL.rotation.x=-.6+Math.sin(state.time*10)*.15;P.elbowL.rotation.x=-1.2;}
