function animateDeath(a,t){const P=a.model.parts,g=a.model.group;const e=Math.min(1,t/.75),ease=e*e*(3-2*e);P.kneeL.rotation.x=P.kneeR.rotation.x=Math.min(1,t/.4)*1.2;P.hipL.rotation.x=P.hipR.rotation.x=-Math.min(1,t/.4)*.6;P.shoulderL.rotation.x=P.shoulderR.rotation.x=-.3-ease*1.4*a.deathDir;P.spine.rotation.x=.3*a.deathDir;g.rotation.set(-a.deathDir*ease*Math.PI/2*.97,a.yaw,0,'YXZ');g.position.set(a.pos.x,a.pos.y+ease*.15,a.pos.z);}

